(3025865, 426533, 3569, '<td valign="top">wonderful curves and lines</td>', 'wonderful curves and lines', '2006-11-13 08:06:48.000000', NULL, 1),
(3025866, 426549, 15711, '<td valign="top">I may not know anything about HDR - but this has POW factor as far as I''m concerned. Each range of color is rich and intense.  Love the symmetry with the bit of counterbalance with the stump( rock?) to the right. 10</td>', 'I may not know anything about HDR - but this has POW factor as far as I''m concerned. Each range of color is rich and intense.  Love the symmetry with the bit of counterbalance with the stump( rock?) to the right. 10', '2006-11-13 08:06:53.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3025867, 426376, 3569, '<td valign="top">nice colors and subject</td>', 'nice colors and subject', '2006-11-13 08:07:00.000000', NULL, 1),
(3025868, 426707, 3569, '<td valign="top">excellent blues</td>', 'excellent blues', '2006-11-13 08:07:12.000000', NULL, 1),
(3025869, 426491, 3569, '<td valign="top">great subject and shot</td>', 'great subject and shot', '2006-11-13 08:07:31.000000', NULL, 1),
(3025890, 426392, 18219, '<td valign="top">I''m only a quarter of the way through voting, but I predict good things for this photograph.<br/>the depth of field along with the unusual point of view AND the HDR makes this a ribbon contender.<br/>Although I have been wrong in my predictions before :-)</td>', 'I''m only a quarter of the way through voting, but I predict good things for this photograph.the depth of field along with the unusual point of view AND the HDR makes this a ribbon contender.Although I have been wrong in my predictions before :-)', '2006-11-13 08:15:24.000000', NULL, 1),
(3025894, 426765, 18219, '<td valign="top">this image still seems a little too dark?</td>', 'this image still seems a little too dark?', '2006-11-13 08:15:59.000000', NULL, 1),
(3025896, 426521, 18219, '<td valign="top">the sky still looks very flat and blown out even with the HDR.<br/>and to be honest, the overall scene isn''t that interesting.<br/>the trees look like they have some good color in them, but they are too far away to really grab your attention.<br/>sorry :-(</td>', 'the sky still looks very flat and blown out even with the HDR.and to be honest, the overall scene isn''t that interesting.the trees look like they have some good color in them, but they are too far away to really grab your attention.sorry :-(', '2006-11-13 08:17:49.000000', NULL, 1),
(3025900, 426768, 18219, '<td valign="top">the barn looks very interesting with some nice textures going on, but i wish the image was a little bigger or the barn filled more of the frame so that more focus was on the textures.</td>', 'the barn looks very interesting with some nice textures going on, but i wish the image was a little bigger or the barn filled more of the frame so that more focus was on the textures.', '2006-11-13 08:19:04.000000', NULL, 1),
(3025919, 426705, 67258, '<td valign="top">For real?</td>', 'For real?', '2006-11-13 08:25:07.000000', NULL, 1),
(3025924, 426755, 67258, '<td valign="top">The greens are a little too over-saturated for my taste.</td>', 'The greens are a little too over-saturated for my taste.', '2006-11-13 08:26:05.000000', NULL, 1),
(3025925, 426155, 67258, '<td valign="top">Rather too bland.</td>', 'Rather too bland.', '2006-11-13 08:26:32.000000', NULL, 1),
(3026013, 426669, 66384, '<td valign="top">Absolutely stunning!!</td>', 'Absolutely stunning!!', '2006-11-13 09:09:17.000000', NULL, 1),
(3026022, 426669, 51538, '<td valign="top">My favourite of this challenge.  The lighting and basic composition are quite pleasant. I think you could do even better in this line of still life photography.<br/><br/><i>Message edited by author 2006-11-20 06:41:37.</i></td>', 'My favourite of this challenge.  The lighting and basic composition are quite pleasant. I think you could do even better in this line of still life photography.', '2006-11-13 09:11:44.000000', '2006-11-20 06:41:37.000000', 1),
(3026024, 426785, 51538, '<td valign="top">Lovely warm subtle tones herein. 8.</td>', 'Lovely warm subtle tones herein. 8.', '2006-11-13 09:12:07.000000', NULL, 1),
(3026025, 426317, 66384, '<td valign="top">Very very nice. The crisp effect of a fine painting.</td>', 'Very very nice. The crisp effect of a fine painting.', '2006-11-13 09:12:13.000000', NULL, 1),
(3026070, 426346, 66384, '<td valign="top">I like the colors and composition, and I would have scored it higher is the focus was sharper.</td>', 'I like the colors and composition, and I would have scored it higher is the focus was sharper.', '2006-11-13 09:20:06.000000', NULL, 1),
(3026083, 426573, 45524, '<td valign="top">I love the colors and the leading pathway that draws my attention, I wish you had brought out a bit more detail in the shadows given the challenge options though. NIcely done and a 7 from me.</td>', 'I love the colors and the leading pathway that draws my attention, I wish you had brought out a bit more detail in the shadows given the challenge options though. NIcely done and a 7 from me.', '2006-11-13 09:24:08.000000', NULL, 1),
(3026088, 426410, 45524, '<td valign="top">THis is a nice composition, however it seems a bit flat on color and saturation. I also wish you had brought out more detail in the shadows. This is a 6 from me.</td>', 'THis is a nice composition, however it seems a bit flat on color and saturation. I also wish you had brought out more detail in the shadows. This is a 6 from me.', '2006-11-13 09:25:10.000000', NULL, 1),
(3026105, 426740, 45524, '<td valign="top">This image really doesnt have much of a point of interest and lacks colors and pop that one would expect from a HDR photo. The shadows have no detail. This is a 5 from me</td>', 'This image really doesnt have much of a point of interest and lacks colors and pop that one would expect from a HDR photo. The shadows have no detail. This is a 5 from me', '2006-11-13 09:30:44.000000', NULL, 1),
(3026108, 426745, 45524, '<td valign="top">Nicely done photo. I wish you had saturated it a bit more to bring out the colors though. Great perspective and composition though. 6</td>', 'Nicely done photo. I wish you had saturated it a bit more to bring out the colors though. Great perspective and composition though. 6', '2006-11-13 09:31:36.000000', NULL, 1),
(3026110, 426396, 45524, '<td valign="top">This is a nicely done HDR photo. It has a nice compostion and wonderfully colored. This is a 7 from me.</td>', 'This is a nicely done HDR photo. It has a nice compostion and wonderfully colored. This is a 7 from me.', '2006-11-13 09:32:58.000000', NULL, 1),
(3026115, 426463, 45524, '<td valign="top">I''m not sure about the HDR portion of this. It seems you have lost the detail in the shadows and there isnt much saturation to the photo. I do like the composition and how the tree at the top seems to frame the point of interest to my eyes.</td>', 'I''m not sure about the HDR portion of this. It seems you have lost the detail in the shadows and there isnt much saturation to the photo. I do like the composition and how the tree at the top seems to frame the point of interest to my eyes.', '2006-11-13 09:34:25.000000', NULL, 1),
(3026120, 426340, 45524, '<td valign="top">Another nicely colored, saturated photo with wonderful detail in the shadows, meets the challenge well. I could see this on a wall at my dentist office if there was a clown reading a paper on the bench(there is a photo very similar to this with just what I added at my dentist office BTW) This is a 7 from me.</td>', 'Another nicely colored, saturated photo with wonderful detail in the shadows, meets the challenge well. I could see this on a wall at my dentist office if there was a clown reading a paper on the bench(there is a photo very similar to this with just what I added at my dentist office BTW) This is a 7 from me.', '2006-11-13 09:37:15.000000', NULL, 1),
(3026122, 426549, 45524, '<td valign="top">Wonderfully done photo for the challenge. I wish it were framed with the tree in the middle, more over to the left and some negative space on the right. But thats likely just a personal preference as I dont like centering of photos too much. This is a 7 from me.</td>', 'Wonderfully done photo for the challenge. I wish it were framed with the tree in the middle, more over to the left and some negative space on the right. But thats likely just a personal preference as I dont like centering of photos too much. This is a 7 from me.', '2006-11-13 09:38:17.000000', NULL, 1),
(3026128, 426414, 45524, '<td valign="top">This is a lovely photo but seems to be desaturated and somewhat flat. I''d like to see more pop in the colors and more detail in the shadows. It seems a bit too dark given the possibilities in the challenge. 6</td>', 'This is a lovely photo but seems to be desaturated and somewhat flat. I''d like to see more pop in the colors and more detail in the shadows. It seems a bit too dark given the possibilities in the challenge. 6', '2006-11-13 09:39:32.000000', NULL, 1),
(3026132, 426485, 45524, '<td valign="top">I can see this photo in the top 5. I love the coloring and the great use of HDR to get it there. Saturation is just about right and nice composition with details taken care of. this is a 9 from me.</td>', 'I can see this photo in the top 5. I love the coloring and the great use of HDR to get it there. Saturation is just about right and nice composition with details taken care of. this is a 9 from me.', '2006-11-13 09:40:19.000000', NULL, 1),
(3026134, 426785, 45524, '<td valign="top">Lovely landscape and nicely composed. It seems a touch on the dark side on my calibrated monitor. ALso I''d like to see some more saturation in the colors. 6</td>', 'Lovely landscape and nicely composed. It seems a touch on the dark side on my calibrated monitor. ALso I''d like to see some more saturation in the colors. 6', '2006-11-13 09:41:32.000000', NULL, 1),
(3026138, 426532, 45524, '<td valign="top">This will ultimatley be DQ''ed for the text added by the use of what I assume is a trial program. I like the composition and your take on it though. Need to save at max size for challenges whatever that is for the challenge.</td>', 'This will ultimatley be DQ''ed for the text added by the use of what I assume is a trial program. I like the composition and your take on it though. Need to save at max size for challenges whatever that is for the challenge.', '2006-11-13 09:42:54.000000', NULL, 1),
(3026140, 426800, 45524, '<td valign="top">THis is a well done HDR with nice details in the whole photo.</td>', 'THis is a well done HDR with nice details in the whole photo.', '2006-11-13 09:43:28.000000', NULL, 1),
(3026141, 426246, 45524, '<td valign="top">Great use of the challenge to get a wonderful image. THis is a 7 from me in this challenge.</td>', 'Great use of the challenge to get a wonderful image. THis is a 7 from me in this challenge.', '2006-11-13 09:44:24.000000', NULL, 1),
(3026145, 426802, 45524, '<td valign="top">I can see a top 10 for this photo. I like the effect you have done with PP meets the challenge well. 8 from me.</td>', 'I can see a top 10 for this photo. I like the effect you have done with PP meets the challenge well. 8 from me.', '2006-11-13 09:45:46.000000', NULL, 1),
(3026147, 426315, 45524, '<td valign="top">Well done HDR and nicely composed. I feel this is a top 10 in this challenge. Well done and an 8 from me.</td>', 'Well done HDR and nicely composed. I feel this is a top 10 in this challenge. Well done and an 8 from me.', '2006-11-13 09:47:14.000000', NULL, 1),
(3026150, 426763, 45524, '<td valign="top">I dont really find a point of interest in the photo. Or anything that really draws my attention. I like the colors and the saturation level though. 5</td>', 'I dont really find a point of interest in the photo. Or anything that really draws my attention. I like the colors and the saturation level though. 5', '2006-11-13 09:48:05.000000', NULL, 1),
(3026151, 426717, 24454, '<td valign="top">Wow!  Wow!   This looks like a magical crystal city!   Perfect range of the light and the shadows.  I''m so impressed that you can even read the signs it is so sharp and clear!   I certainly don''t know much about HDR, but to me, this looks like the perfect photo!</td>', 'Wow!  Wow!   This looks like a magical crystal city!   Perfect range of the light and the shadows.  I''m so impressed that you can even read the signs it is so sharp and clear!   I certainly don''t know much about HDR, but to me, this looks like the perfect photo!', '2006-11-13 09:48:59.000000', NULL, 1),
(3026152, 426786, 45524, '<td valign="top">THis is a nice HDR and also IR photo. I like the composition but I wonder what this same photo would look like in color. I think in this particular challenge it might had done better in color. 7</td>', 'THis is a nice HDR and also IR photo. I like the composition but I wonder what this same photo would look like in color. I think in this particular challenge it might had done better in color. 7', '2006-11-13 09:49:40.000000', NULL, 1),
(3026153, 426246, 24454, '<td valign="top">This has stunning everything:  subject, exposure, colors, range, composition.   I love the perfectly formed stars of light that don''t look the least bit blown out or over-exposed.  You did really great!  Congratulations!  10</td>', 'This has stunning everything:  subject, exposure, colors, range, composition.   I love the perfectly formed stars of light that don''t look the least bit blown out or over-exposed.  You did really great!  Congratulations!  10', '2006-11-13 09:51:14.000000', NULL, 1),
(3026156, 426734, 64929, '<td valign="top">Great shot!  Needs to be straightened a bit, though</td>', 'Great shot!  Needs to be straightened a bit, though', '2006-11-13 09:51:53.000000', NULL, 1),
(3026160, 426734, 45524, '<td valign="top">This is well done and works well within the challenge. I wish the horizon had been a little straighter, I keep wanting to tilt my head to the right to straighten. I also wish I had the whole reflection. HOwever I realize that without going super wide or further away that maynot be possible. this is a 7 from me.</td>', 'This is well done and works well within the challenge. I wish the horizon had been a little straighter, I keep wanting to tilt my head to the right to straighten. I also wish I had the whole reflection. HOwever I realize that without going super wide or further away that maynot be possible. this is a 7 from me.', '2006-11-13 09:52:20.000000', NULL, 1),
(3026162, 426564, 45524, '<td valign="top">This is a nice example of an HDR. Meets the challenge well is nicely colored and composed. I like the perspective as well. 7</td>', 'This is a nice example of an HDR. Meets the challenge well is nicely colored and composed. I like the perspective as well. 7', '2006-11-13 09:53:17.000000', NULL, 1),
(3026163, 426705, 24454, '<td valign="top">Ohmygosh. . .I am certainly not an expert on HDR, but this is the most awesome photo of a bird I have ever seen!  Is that for real???   No photoshop tricks to get that butterfly perfectly situated on that bird''s beak???   This may be one of my favorites of my favorites!  10, 10, 10!!!</td>', 'Ohmygosh. . .I am certainly not an expert on HDR, but this is the most awesome photo of a bird I have ever seen!  Is that for real???   No photoshop tricks to get that butterfly perfectly situated on that bird''s beak???   This may be one of my favorites of my favorites!  10, 10, 10!!!', '2006-11-13 09:53:30.000000', NULL, 1),
(3026167, 426317, 45524, '<td valign="top">Meets the challenge well. Seems well done and nicely colored. 7</td>', 'Meets the challenge well. Seems well done and nicely colored. 7', '2006-11-13 09:54:13.000000', NULL, 1),
(3026171, 426700, 24454, '<td valign="top">Wow!  GREAT JOB!  I''m not an expert on HDR, but this seems to me like a flawless representation of the light, colors and shadows range!  Plus. . .I love cows! :)</td>', 'Wow!  GREAT JOB!  I''m not an expert on HDR, but this seems to me like a flawless representation of the light, colors and shadows range!  Plus. . .I love cows! :)', '2006-11-13 09:55:10.000000', NULL, 1),
(3026173, 426414, 36382, '<td valign="top">Seems a little dark, especially the sky</td>', 'Seems a little dark, especially the sky', '2006-11-13 09:55:56.000000', NULL, 1),
(3026176, 426491, 45524, '<td valign="top">There are a couple of things in this photo that bother me, however I can see this at least with a top 5. Maybe even a ribbon. I''m sure thats a flock of birds or something in the sky. But they are really distracting. This is still a 8 from me. But likely would have been a 10 without the distractions in the sky.</td>', 'There are a couple of things in this photo that bother me, however I can see this at least with a top 5. Maybe even a ribbon. I''m sure thats a flock of birds or something in the sky. But they are really distracting. This is still a 8 from me. But likely would have been a 10 without the distractions in the sky.', '2006-11-13 09:56:02.000000', NULL, 1),
(3026180, 426396, 24454, '<td valign="top">I really love this one.   I''m always so impressed when someone can take an ordinary photo -- like of a working tractor -- and turn it into beautiful vibrant photography!   As little as I know about HDR, it does seem to me that there is excellent range of color, light and shadows!   Great job.</td>', 'I really love this one.   I''m always so impressed when someone can take an ordinary photo -- like of a working tractor -- and turn it into beautiful vibrant photography!   As little as I know about HDR, it does seem to me that there is excellent range of color, light and shadows!   Great job.', '2006-11-13 09:57:06.000000', NULL, 1),
(3026181, 426734, 36382, '<td valign="top">I wish I could see the whole reflection of the building.  I like the color.  Looks like you pumped them up a bit, but it works for me.</td>', 'I wish I could see the whole reflection of the building.  I like the color.  Looks like you pumped them up a bit, but it works for me.', '2006-11-13 09:58:04.000000', NULL, 1),
(3026185, 426396, 36382, '<td valign="top">Excellent.  sky looks great.</td>', 'Excellent.  sky looks great.', '2006-11-13 09:59:34.000000', NULL, 1),
(3026190, 426226, 36382, '<td valign="top">Looks very real, like you could touch the flowers</td>', 'Looks very real, like you could touch the flowers', '2006-11-13 10:00:58.000000', NULL, 1),
(3026193, 426152, 24454, '<td valign="top">How pretty with those amazing blue highlights in that forest!  Great job!</td>', 'How pretty with those amazing blue highlights in that forest!  Great job!', '2006-11-13 10:01:51.000000', NULL, 1),
(3026198, 426266, 24454, '<td valign="top">I love this photo!  I love the composition and angle of the pier!  It''s a beautiful dramatic photo!</td>', 'I love this photo!  I love the composition and angle of the pier!  It''s a beautiful dramatic photo!', '2006-11-13 10:02:40.000000', NULL, 1),
(3026201, 426498, 24454, '<td valign="top">What an elegant photo!</td>', 'What an elegant photo!', '2006-11-13 10:03:56.000000', NULL, 1),
(3026206, 426691, 24454, '<td valign="top">How PRETTY!   I love the reflection showing the autumn trees, but not being able to see the trees.  It makes a wonderful composition!  It does in fact look like a water color painting!  Beautiful job.</td>', 'How PRETTY!   I love the reflection showing the autumn trees, but not being able to see the trees.  It makes a wonderful composition!  It does in fact look like a water color painting!  Beautiful job.', '2006-11-13 10:05:37.000000', NULL, 1),
(3026213, 426824, 24454, '<td valign="top">This is very good!  Having tried to photograph the skyline over Town Lake several times -- I understand particularly how hard it is to get the correct exposure on that Frost Tower -- it seems that NOTHING keeps it from being over-exposed -- so to me -- you have utilized HDR to perfection -- and I LOVE this beautiful photo!</td>', 'This is very good!  Having tried to photograph the skyline over Town Lake several times -- I understand particularly how hard it is to get the correct exposure on that Frost Tower -- it seems that NOTHING keeps it from being over-exposed -- so to me -- you have utilized HDR to perfection -- and I LOVE this beautiful photo!', '2006-11-13 10:07:58.000000', NULL, 1),
(3026225, 426272, 24454, '<td valign="top">What a beautiful scene!  A work of art.   As little as I know about HDR, this seems like such a perfect representation of the range of light, shadows and color!   I just love this photo!  10</td>', 'What a beautiful scene!  A work of art.   As little as I know about HDR, this seems like such a perfect representation of the range of light, shadows and color!   I just love this photo!  10', '2006-11-13 10:11:28.000000', NULL, 1),
(3026235, 426523, 24454, '<td valign="top">Oh, I LOVE IT! These striking rock formations make such interesting photos.  And I do love the range of light, shadows and colors you have achieved.  Great job!</td>', 'Oh, I LOVE IT! These striking rock formations make such interesting photos.  And I do love the range of light, shadows and colors you have achieved.  Great job!', '2006-11-13 10:14:08.000000', NULL, 1),
(3026239, 426768, 24454, '<td valign="top">This is beautiful!  Wonderful rich range of colors and light!</td>', 'This is beautiful!  Wonderful rich range of colors and light!', '2006-11-13 10:15:13.000000', NULL, 1),
(3026244, 426485, 24454, '<td valign="top">This is very striking!   And who hasn''t shot enough photos of the sun, only to get everything else silhouetted to know that this is an excellent representation of HDR!  Fantastic job!</td>', 'This is very striking!   And who hasn''t shot enough photos of the sun, only to get everything else silhouetted to know that this is an excellent representation of HDR!  Fantastic job!', '2006-11-13 10:16:30.000000', NULL, 1),
(3026251, 426707, 24454, '<td valign="top">Oh man!  This is awesome!   What a beautiful job of lighting, colors, composition, subject!  Fantastic job!</td>', 'Oh man!  This is awesome!   What a beautiful job of lighting, colors, composition, subject!  Fantastic job!', '2006-11-13 10:17:19.000000', NULL, 1),
(3026257, 426315, 24454, '<td valign="top">What a COOL composition!   That truck gives it such a nostalgic feel -- and the boat gives it such a dramatic feel!  I love it!</td>', 'What a COOL composition!   That truck gives it such a nostalgic feel -- and the boat gives it such a dramatic feel!  I love it!', '2006-11-13 10:18:09.000000', NULL, 1),
(3026259, 426802, 24454, '<td valign="top">How GORGEOUS!   I wish I could see the whole person in blue, but the photo is so incredible in every other way -- it is only a minor distraction!  There''s such a stunning display of light, colors, shadows.  I''m not an expert on HDR, but from what I know, this certainly looks like a fine example to learn from!  9</td>', 'How GORGEOUS!   I wish I could see the whole person in blue, but the photo is so incredible in every other way -- it is only a minor distraction!  There''s such a stunning display of light, colors, shadows.  I''m not an expert on HDR, but from what I know, this certainly looks like a fine example to learn from!  9', '2006-11-13 10:19:48.000000', NULL, 1),
(3026267, 426745, 24454, '<td valign="top">Hamilton''s Pool!   I LOVE this!  Last time I tried to photograph it, I was hard pressed not to get a million people in it!   I think I need to make a trip back there.   You''ve inspired me :)  Nice job.</td>', 'Hamilton''s Pool!   I LOVE this!  Last time I tried to photograph it, I was hard pressed not to get a million people in it!   I think I need to make a trip back there.   You''ve inspired me :)  Nice job.', '2006-11-13 10:22:23.000000', NULL, 1),
(3026269, 426740, 24454, '<td valign="top">Gasp!   This is STUNNING!   And I feel quite sure that this was more than likely a very dark cave, so your ability to bring light and rich color into it is awe inspiring!  10</td>', 'Gasp!   This is STUNNING!   And I feel quite sure that this was more than likely a very dark cave, so your ability to bring light and rich color into it is awe inspiring!  10', '2006-11-13 10:24:04.000000', NULL, 1),
(3026271, 426546, 24454, '<td valign="top">How cool!   I love this effect!  My only tiny nit-pick is that it seems a little tilted -- but it looks so cool anyway that it''s just a little distraction.</td>', 'How cool!   I love this effect!  My only tiny nit-pick is that it seems a little tilted -- but it looks so cool anyway that it''s just a little distraction.', '2006-11-13 10:24:53.000000', NULL, 1),
(3026275, 426303, 24454, '<td valign="top">How PRETTY!  Amazing job showing this strong range of light and darkness!  I love this!</td>', 'How PRETTY!  Amazing job showing this strong range of light and darkness!  I love this!', '2006-11-13 10:26:00.000000', NULL, 1),
(3026279, 426549, 24454, '<td valign="top">So incredible!!!!!!</td>', 'So incredible!!!!!!', '2006-11-13 10:26:43.000000', NULL, 1),
(3026284, 426485, 52439, '<td valign="top">Nice shot for sure, contrast is abit extreme though.</td>', 'Nice shot for sure, contrast is abit extreme though.', '2006-11-13 10:27:52.000000', NULL, 1),
(3026286, 426498, 52439, '<td valign="top">Wow.<br/>Really excellent shot.<br/>9 from me.</td>', 'Wow.Really excellent shot.9 from me.', '2006-11-13 10:28:27.000000', NULL, 1),
(3026288, 426785, 24454, '<td valign="top">Excellent!  Not an expert on HDR by any means, but this certainly seems to be a perfect study in it with such a beautiful range of light, shadow and color!  The sunrays make it such a dramatic photo!</td>', 'Excellent!  Not an expert on HDR by any means, but this certainly seems to be a perfect study in it with such a beautiful range of light, shadow and color!  The sunrays make it such a dramatic photo!', '2006-11-13 10:28:42.000000', NULL, 1),
(3026292, 426790, 52439, '<td valign="top">Just needs a bit more of a punch, perhaps boosting the contrast would make it less ''flat''.</td>', 'Just needs a bit more of a punch, perhaps boosting the contrast would make it less ''flat''.', '2006-11-13 10:29:02.000000', NULL, 1),
(3026294, 426669, 52439, '<td valign="top">Nice shot, think certain things are lost in the flowers though.</td>', 'Nice shot, think certain things are lost in the flowers though.', '2006-11-13 10:29:36.000000', NULL, 1),
(3026295, 426315, 52439, '<td valign="top">Good shot.<br/>Looks almost like a painting.</td>', 'Good shot.Looks almost like a painting.', '2006-11-13 10:30:03.000000', NULL, 1),
