(3027105, 426315, 42100, '<td valign="top">The HDR rendered a lot less realistic looking photo in this case, but I do like the results.  This interesting and fairly dynamic composition combined with the processing give this very good art appeal.  Nicely done!</td>', 'The HDR rendered a lot less realistic looking photo in this case, but I do like the results.  This interesting and fairly dynamic composition combined with the processing give this very good art appeal.  Nicely done!', '2006-11-13 14:19:37.000000', NULL, 1),
(3027109, 426734, 67152, '<td valign="top">Use of Light:2<br/>Focus:2<br/>Composition:2<br/>Creativity:1<br/>Achieves Challenge:1<br/>Color -1<br/> <br/>The use of HDR to bring out the tires in the pond was excellent.  However, the colors of the trees, flowers and water are too vibrant for my taste.</td>', 'Use of Light:2Focus:2Composition:2Creativity:1Achieves Challenge:1Color -1 The use of HDR to bring out the tires in the pond was excellent.  However, the colors of the trees, flowers and water are too vibrant for my taste.', '2006-11-13 14:20:05.000000', NULL, 1),
(3027120, 426498, 60805, '<td valign="top">looks like torture for her, holding that pose for the recommended 7 shots.<br/>7 for the image and 2 for her pain and suffering :) 9</td>', 'looks like torture for her, holding that pose for the recommended 7 shots.7 for the image and 2 for her pain and suffering :) 9', '2006-11-13 14:23:03.000000', NULL, 1),
