(3030335, 426420, 37608, '<td valign="top">good color</td>', 'good color', '2006-11-14 12:12:24.000000', NULL, 1),
(3030407, 426272, 32754, '<td valign="top">lovely tones...beautifully done.</td>', 'lovely tones...beautifully done.', '2006-11-14 12:44:06.000000', NULL, 1),
(3030408, 426212, 32754, '<td valign="top">I like the extremes of tone here...well done...the sky adds movement and some sort of tension, too.</td>', 'I like the extremes of tone here...well done...the sky adds movement and some sort of tension, too.', '2006-11-14 12:44:36.000000', NULL, 1),
(3030409, 426396, 32754, '<td valign="top">I like the tonal range here...it''s very dramatic.</td>', 'I like the tonal range here...it''s very dramatic.', '2006-11-14 12:44:58.000000', NULL, 1),
(3030412, 426785, 32754, '<td valign="top">The dynamic range here seems soft, yet lovely and well composed.</td>', 'The dynamic range here seems soft, yet lovely and well composed.', '2006-11-14 12:45:29.000000', NULL, 1),
(3030416, 426734, 32754, '<td valign="top">Great shot!...well done dynamically...love it...uniform and balanced with enough tension to create interest.</td>', 'Great shot!...well done dynamically...love it...uniform and balanced with enough tension to create interest.', '2006-11-14 12:46:16.000000', NULL, 1),
(3030417, 426539, 32754, '<td valign="top">Fascinating image...beautifully composed.</td>', 'Fascinating image...beautifully composed.', '2006-11-14 12:46:32.000000', NULL, 1),
(3030427, 426813, 17279, '<td valign="top">Overall, this image is too dark and the red color cast seems unnatural.</td>', 'Overall, this image is too dark and the red color cast seems unnatural.', '2006-11-14 12:49:48.000000', NULL, 1),
(3030430, 426781, 17279, '<td valign="top">There''s too much going on in this image, with no central point of interest.  The processing also seems a bit harsh, particularly on the foliage in the background.</td>', 'There''s too much going on in this image, with no central point of interest.  The processing also seems a bit harsh, particularly on the foliage in the background.', '2006-11-14 12:51:05.000000', NULL, 1),
(3030432, 426820, 17279, '<td valign="top">I would have liked to see the structures take up much more of the image.  They provide a great deal more interest than the sky, which makes up most of this image.</td>', 'I would have liked to see the structures take up much more of the image.  They provide a great deal more interest than the sky, which makes up most of this image.', '2006-11-14 12:52:05.000000', NULL, 1),
(3030434, 426804, 17279, '<td valign="top">There''s no real central point of interest here.  While the colors are nice, my eyes don''t really know where to go.</td>', 'There''s no real central point of interest here.  While the colors are nice, my eyes don''t really know where to go.', '2006-11-14 12:52:45.000000', NULL, 1),
(3030438, 426523, 17279, '<td valign="top">This subject doesn''t really capture my attention.  I think the foreground actually provides more interest than the main rock.</td>', 'This subject doesn''t really capture my attention.  I think the foreground actually provides more interest than the main rock.', '2006-11-14 12:53:50.000000', NULL, 1),
(3030441, 426484, 17279, '<td valign="top">This is a hard subject to photograph what with all the different reflections.  There''s no central point of interest and too many reflective highlights here.</td>', 'This is a hard subject to photograph what with all the different reflections.  There''s no central point of interest and too many reflective highlights here.', '2006-11-14 12:54:47.000000', NULL, 1),
(3030445, 426399, 17279, '<td valign="top">The lights above the walkway are fascinating, while the people are uninteresting.  Perhaps a different composition focusing predominantly on the lights?</td>', 'The lights above the walkway are fascinating, while the people are uninteresting.  Perhaps a different composition focusing predominantly on the lights?', '2006-11-14 12:55:35.000000', NULL, 1),
(3030449, 426729, 17279, '<td valign="top">There''s too much empty space here.  I think the people should take up more of the image.  The color cast seems off to me as well.</td>', 'There''s too much empty space here.  I think the people should take up more of the image.  The color cast seems off to me as well.', '2006-11-14 12:56:25.000000', NULL, 1),
(3030452, 426789, 17279, '<td valign="top">Nice subject, but the car on the right detracts, and the sky is bland and uninteresting (although there''s not much you can do about that).</td>', 'Nice subject, but the car on the right detracts, and the sky is bland and uninteresting (although there''s not much you can do about that).', '2006-11-14 12:57:16.000000', NULL, 1),
(3030456, 426765, 17279, '<td valign="top">This image does very little for me.  Overall it''s still a bit dark (on my monitor) while the reeds in the foreground seem overexposed.</td>', 'This image does very little for me.  Overall it''s still a bit dark (on my monitor) while the reeds in the foreground seem overexposed.', '2006-11-14 12:58:31.000000', NULL, 1),
(3030461, 426708, 17279, '<td valign="top">My overall impression is that the subject is rather uninteresting and bland.  You cut off the mountain at the top and left only a little sky on each side.  I think this would do better if it was recomposed.</td>', 'My overall impression is that the subject is rather uninteresting and bland.  You cut off the mountain at the top and left only a little sky on each side.  I think this would do better if it was recomposed.', '2006-11-14 12:59:55.000000', NULL, 1),
(3030464, 426486, 17279, '<td valign="top">A rather uninteresting alley with too much going on.  The drain cover in the foreground is not strong enough to overcome that.</td>', 'A rather uninteresting alley with too much going on.  The drain cover in the foreground is not strong enough to overcome that.', '2006-11-14 13:01:10.000000', NULL, 1),
(3030466, 426700, 17279, '<td valign="top">Beautiful colors, but the subject is uninteresting and does not really enhance the overall image.</td>', 'Beautiful colors, but the subject is uninteresting and does not really enhance the overall image.', '2006-11-14 13:01:54.000000', NULL, 1),
(3030556, 426539, 13207, '<td valign="top">Almost looks like it''s underwater - I like this a lot</td>', 'Almost looks like it''s underwater - I like this a lot', '2006-11-14 13:43:59.000000', NULL, 1),
(3030629, 426803, 12243, '<td valign="top">ok, i am quite sure this is Somersby falls. I was comparing the rocks to my shot and i am 99.9% sure it is. That being said, i wonder who took it? Keegbow maybe? Either way it is a lovely shot, well done :)</td>', 'ok, i am quite sure this is Somersby falls. I was comparing the rocks to my shot and i am 99.9% sure it is. That being said, i wonder who took it? Keegbow maybe? Either way it is a lovely shot, well done :)', '2006-11-14 14:11:47.000000', NULL, 1),
(3030630, 426246, 12243, '<td valign="top">oooh very nice love. Makes me feel dizzy when i look at it</td>', 'oooh very nice love. Makes me feel dizzy when i look at it', '2006-11-14 14:12:38.000000', NULL, 1),
(3030657, 426569, 53316, '<td valign="top">Seems a bit busy to me with no real focal point. But I love the colors and the reflections.</td>', 'Seems a bit busy to me with no real focal point. But I love the colors and the reflections.', '2006-11-14 14:20:03.000000', NULL, 1),
(3030663, 426365, 53316, '<td valign="top">I feel as though something is lacking but I can''t put my finger on it. Maybe the image looks a bit too flat?  Anyway, the colors are just great and I like the composition.</td>', 'I feel as though something is lacking but I can''t put my finger on it. Maybe the image looks a bit too flat?  Anyway, the colors are just great and I like the composition.', '2006-11-14 14:21:04.000000', NULL, 1),
(3030666, 426740, 53316, '<td valign="top">Hm, the bit of greenish looking thing in the upper center is a bit distracting. But the photo as a whole is very stunning. A great subject and a great presentation - a nice abstract image.</td>', 'Hm, the bit of greenish looking thing in the upper center is a bit distracting. But the photo as a whole is very stunning. A great subject and a great presentation - a nice abstract image.', '2006-11-14 14:22:24.000000', NULL, 1),
(3030671, 426410, 53316, '<td valign="top">Seems like the whole photo is a bit too dark, but I kind of think that adds to the "feel" of the shot.  Very lovely colors and composition.</td>', 'Seems like the whole photo is a bit too dark, but I kind of think that adds to the "feel" of the shot.  Very lovely colors and composition.', '2006-11-14 14:23:08.000000', NULL, 1),
(3030672, 426246, 53316, '<td valign="top">Ummmm.... wow. Beautiful.  My only nitpick is that it seems, when I look at the two windows in the very back (center) it seems like things are not aligned, which I think is very visually important in shots like this... regardless, that is a nitpick, as I said, and I think this is a gorgeous shot.</td>', 'Ummmm.... wow. Beautiful.  My only nitpick is that it seems, when I look at the two windows in the very back (center) it seems like things are not aligned, which I think is very visually important in shots like this... regardless, that is a nitpick, as I said, and I think this is a gorgeous shot.', '2006-11-14 14:23:13.000000', NULL, 1),
(3030676, 426558, 53316, '<td valign="top">Beautiful!! Wonderful colors, dramatic clouds... and the way the light is in the upper left corner is just amazing.</td>', 'Beautiful!! Wonderful colors, dramatic clouds... and the way the light is in the upper left corner is just amazing.', '2006-11-14 14:24:04.000000', NULL, 1),
(3030718, 426650, 59458, '<td valign="top">This one looks like a regular shot to me. I gave it a 5.</td>', 'This one looks like a regular shot to me. I gave it a 5.', '2006-11-14 14:47:51.000000', NULL, 1),
(3030777, 426520, 41554, '<td valign="top">This is really nice and must have been very hard to shoot...</td>', 'This is really nice and must have been very hard to shoot...', '2006-11-14 15:15:33.000000', NULL, 1),
(3030780, 426317, 41554, '<td valign="top">Nice colour tones. The small patch of blown sky on the left is a bit distracting IMHO.</td>', 'Nice colour tones. The small patch of blown sky on the left is a bit distracting IMHO.', '2006-11-14 15:16:39.000000', NULL, 1),
(3030787, 426226, 41554, '<td valign="top">I think you were trying to get the most of the technique, but the result is a bit too busy for my taste. Great sharpness and clarity.</td>', 'I think you were trying to get the most of the technique, but the result is a bit too busy for my taste. Great sharpness and clarity.', '2006-11-14 15:18:33.000000', NULL, 1),
(3030792, 426546, 41554, '<td valign="top">Very nice shot. The chevy looks "cartoonish" and the whole pic just works.</td>', 'Very nice shot. The chevy looks "cartoonish" and the whole pic just works.', '2006-11-14 15:20:07.000000', NULL, 1),
(3030799, 426485, 41554, '<td valign="top">Sand like snow, sky like fire. Too bad the sea was flat...</td>', 'Sand like snow, sky like fire. Too bad the sea was flat...', '2006-11-14 15:22:57.000000', NULL, 1),
(3030950, 426303, 15574, '<td valign="top">This is outstanding..</td>', 'This is outstanding..', '2006-11-14 16:12:10.000000', NULL, 1),
(3030995, 426396, 55822, '<td valign="top">I really like this shot but the colors are almost too saturated for me. I''m not sure if that is something you upped or if its from doing HDR. Overall though very nice shot.</td>', 'I really like this shot but the colors are almost too saturated for me. I''m not sure if that is something you upped or if its from doing HDR. Overall though very nice shot.', '2006-11-14 16:31:16.000000', NULL, 1),
(3031001, 426315, 55822, '<td valign="top">I love the desaturation of the colors, yet you were able to keep such great tonal range.</td>', 'I love the desaturation of the colors, yet you were able to keep such great tonal range.', '2006-11-14 16:32:21.000000', NULL, 1),
(3031005, 426546, 55822, '<td valign="top">To me this has a cartoony feel to it. It is very surrealistic.</td>', 'To me this has a cartoony feel to it. It is very surrealistic.', '2006-11-14 16:33:29.000000', NULL, 1),
(3031013, 426740, 55822, '<td valign="top">Very difficult shot to pull off even with HDR. You were able to do this beautifully.</td>', 'Very difficult shot to pull off even with HDR. You were able to do this beautifully.', '2006-11-14 16:35:10.000000', NULL, 1),
(3031015, 426785, 55822, '<td valign="top">WOW, i love the range you have achieved in this shot. The contrast between the clouds and the hills is increadible.</td>', 'WOW, i love the range you have achieved in this shot. The contrast between the clouds and the hills is increadible.', '2006-11-14 16:36:13.000000', NULL, 1),
(3031022, 426226, 55822, '<td valign="top">Great job with the HDR, this is one of the few shots that doesn''t look like it was done in HDR and to me that is an accomplishment.</td>', 'Great job with the HDR, this is one of the few shots that doesn''t look like it was done in HDR and to me that is an accomplishment.', '2006-11-14 16:38:45.000000', NULL, 1),
(3031024, 426734, 55822, '<td valign="top">My only grip about this shot is that the horizon isn''t level. Other than that really good shot with just the right amount of saturation.</td>', 'My only grip about this shot is that the horizon isn''t level. Other than that really good shot with just the right amount of saturation.', '2006-11-14 16:40:08.000000', NULL, 1),
(3031025, 426503, 55822, '<td valign="top">Fantastic shot.</td>', 'Fantastic shot.', '2006-11-14 16:40:45.000000', NULL, 1),
(3031028, 426520, 55822, '<td valign="top">Very cool shot. The girl is the perfect fit for this shot.</td>', 'Very cool shot. The girl is the perfect fit for this shot.', '2006-11-14 16:42:14.000000', NULL, 1),
(3031035, 426717, 52301, '<td valign="top">It''s a nice shot.. Too bad it''s Charlotte NC... That city sucks!</td>', 'It''s a nice shot.. Too bad it''s Charlotte NC... That city sucks!', '2006-11-14 16:45:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3031090, 426376, 67301, '<td valign="top">I like the composition and crop of this shot It has vivid true colour and great DOF. The sky is very dramatic. great photo 9</td>', 'I like the composition and crop of this shot It has vivid true colour and great DOF. The sky is very dramatic. great photo 9', '2006-11-14 17:05:48.000000', NULL, 1),
(3031142, 426315, 20608, '<td valign="top">excellent another one of my picks for top 3 r10</td>', 'excellent another one of my picks for top 3 r10', '2006-11-14 17:24:44.000000', NULL, 1),
(3031321, 426376, 15574, '<td valign="top">Great Color</td>', 'Great Color', '2006-11-14 18:37:31.000000', NULL, 1),
(3031414, 426740, 67152, '<td valign="top">Use of Light:1<br/>Focus:1<br/>Composition:1<br/>Creativity:1<br/>Achieves Challenge:2<br/>Great cave!  I love the use of HDR to bring out the subtleness of this cave - and the colors are not overdone.  Good job.</td>', 'Use of Light:1Focus:1Composition:1Creativity:1Achieves Challenge:2Great cave!  I love the use of HDR to bring out the subtleness of this cave - and the colors are not overdone.  Good job.', '2006-11-14 19:17:50.000000', NULL, 1),
(3031418, 426765, 67152, '<td valign="top">Use of Light:2<br/>Focus:1<br/>Composition:1<br/>Creativity:1<br/>Achieves Challenge:2<br/>Very nice technical use of HDR to highlight the reflection and allowing the grasses to not get blown out.</td>', 'Use of Light:2Focus:1Composition:1Creativity:1Achieves Challenge:2Very nice technical use of HDR to highlight the reflection and allowing the grasses to not get blown out.', '2006-11-14 19:18:52.000000', NULL, 1),
(3031423, 426707, 67152, '<td valign="top">Use of Light:2<br/>Focus:1<br/>Composition:2<br/>Creativity:1<br/>Achieves Challenge:2<br/> <br/>Very good job on the HDR.  THe composition is very nice with just enough of the road in the picture.  The colors seem very real (the greens are not over done like so many in the challenge).</td>', 'Use of Light:2Focus:1Composition:2Creativity:1Achieves Challenge:2 Very good job on the HDR.  THe composition is very nice with just enough of the road in the picture.  The colors seem very real (the greens are not over done like so many in the challenge).', '2006-11-14 19:20:00.000000', NULL, 1),
(3031434, 426813, 52439, '<td valign="top">Lovely colours and sutblety.</td>', 'Lovely colours and sutblety.', '2006-11-14 19:25:49.000000', NULL, 1),
(3031436, 426623, 52439, '<td valign="top">What a sky!</td>', 'What a sky!', '2006-11-14 19:25:59.000000', NULL, 1),
(3031453, 426734, 52439, '<td valign="top">Bold, vibrant and full of what HDR can do.<br/>Well done.</td>', 'Bold, vibrant and full of what HDR can do.Well done.', '2006-11-14 19:33:24.000000', NULL, 1),
(3031454, 426303, 57315, '<td valign="top">This is one of the few images submitted that IMHO actually makes use of HDR to achieve something, an atmosphere that would not be there in standard photography. Anyone can photgraph an amazing building or wonderous landscape and make it look nice, but you''ve done something far more difficult - by turning a most mundane subject into an ethereal journey. You are eally painting with light here and I love it! Sorry I can''t vote as I''m not a paid up member, but I would have given this a 10.</td>', 'This is one of the few images submitted that IMHO actually makes use of HDR to achieve something, an atmosphere that would not be there in standard photography. Anyone can photgraph an amazing building or wonderous landscape and make it look nice, but you''ve done something far more difficult - by turning a most mundane subject into an ethereal journey. You are eally painting with light here and I love it! Sorry I can''t vote as I''m not a paid up member, but I would have given this a 10.', '2006-11-14 19:33:29.000000', NULL, 1),
(3031456, 426152, 52439, '<td valign="top">Love it.</td>', 'Love it.', '2006-11-14 19:33:57.000000', NULL, 1),
(3031471, 426521, 57315, '<td valign="top">If I was to be brutally frank, I''d say there is nothing in this picture that suggests HDR was used at all. It''s flat, dull and pointless. It looks like it was taken on a camera phone through a dirty window. <br/>Luckily I''m not being frank, but I will say perhaps you didn''t follow the HDR proceedure properly? Try looking for more dramatic skies or areas with greater dynamic range - after all that''s what HDR is all about!</td>', 'If I was to be brutally frank, I''d say there is nothing in this picture that suggests HDR was used at all. It''s flat, dull and pointless. It looks like it was taken on a camera phone through a dirty window. Luckily I''m not being frank, but I will say perhaps you didn''t follow the HDR proceedure properly? Try looking for more dramatic skies or areas with greater dynamic range - after all that''s what HDR is all about!', '2006-11-14 19:41:24.000000', NULL, 1),
(3031476, 426303, 23203, '<td valign="top">Really Really Nice. Amazing colors and detail. The centered composition works well.</td>', 'Really Really Nice. Amazing colors and detail. The centered composition works well.', '2006-11-14 19:43:05.000000', NULL, 1),
(3031480, 426745, 23203, '<td valign="top">Lovely composition and detail.<br/>A little more contrast would have added a punch to this. 8</td>', 'Lovely composition and detail.A little more contrast would have added a punch to this. 8', '2006-11-14 19:45:13.000000', NULL, 1),
(3031572, 426800, 67152, '<td valign="top">Use of Light:1<br/>Focus:1<br/>Composition:2<br/>Creativity:1<br/>Achieves Challenge:2<br/>Subtle use of HDR to bring out the details throughout the image</td>', 'Use of Light:1Focus:1Composition:2Creativity:1Achieves Challenge:2Subtle use of HDR to bring out the details throughout the image', '2006-11-14 20:31:32.000000', NULL, 1),
(3031575, 426601, 67152, '<td valign="top">Use of Light:2<br/>Focus:1<br/>Composition:2<br/>Creativity:2<br/>Achieves Challenge:2<br/> <br/>What a crazy shot - and so creative.  The use of the clear lightbulb with HDR is quite unique</td>', 'Use of Light:2Focus:1Composition:2Creativity:2Achieves Challenge:2 What a crazy shot - and so creative.  The use of the clear lightbulb with HDR is quite unique', '2006-11-14 20:32:33.000000', NULL, 1),
(3031576, 426266, 32968, '<td valign="top">I see a slight slant to the left...gotta give it an 9. Great shot tho</td>', 'I see a slight slant to the left...gotta give it an 9. Great shot tho', '2006-11-14 20:32:54.000000', NULL, 1),
(3031580, 426785, 67152, '<td valign="top">Use of Light:2<br/>Focus:1<br/>Composition:2<br/>Creativity:1<br/>Achieves Challenge:2<br/>Mood +1<br/> <br/>I love the subdued colors and the great feel of the clouds bursting with light</td>', 'Use of Light:2Focus:1Composition:2Creativity:1Achieves Challenge:2Mood +1 I love the subdued colors and the great feel of the clouds bursting with light', '2006-11-14 20:33:26.000000', NULL, 1),
(3031583, 426650, 67152, '<td valign="top">Use of Light:1<br/>Focus:1<br/>Composition:1<br/>Creativity:1<br/>Achieves Challenge:2<br/>Talk about subtle use of HDR to bring out the brights of the cloudy day while allowing the details under the bridge</td>', 'Use of Light:1Focus:1Composition:1Creativity:1Achieves Challenge:2Talk about subtle use of HDR to bring out the brights of the cloudy day while allowing the details under the bridge', '2006-11-14 20:34:26.000000', NULL, 1),
(3031585, 426533, 32968, '<td valign="top">Love the road winding it''s way from one corner of the photo to the other. NIce work</td>', 'Love the road winding it''s way from one corner of the photo to the other. NIce work', '2006-11-14 20:34:31.000000', NULL, 1),
(3031586, 426742, 67152, '<td valign="top">Use of Light:1<br/>Focus:1<br/>Composition:2<br/>Creativity:1<br/>Achieves Challenge:1<br/>Color -1<br/> <br/>The colors seem extreme with the purple around the mountains.</td>', 'Use of Light:1Focus:1Composition:2Creativity:1Achieves Challenge:1Color -1 The colors seem extreme with the purple around the mountains.', '2006-11-14 20:35:16.000000', NULL, 1),
(3031587, 426486, 32968, '<td valign="top">Nice work. Makes a somewhat grungy place look good.</td>', 'Nice work. Makes a somewhat grungy place look good.', '2006-11-14 20:35:18.000000', NULL, 1),
(3031591, 426569, 67152, '<td valign="top">Use of Light:2<br/>Focus:1<br/>Composition:2<br/>Creativity:1<br/>Achieves Challenge:2<br/> <br/>I really like the motion that the leaves give to the photo.  Use of HDR is pretty subtle (a good thing!) but the colors seem a tad vibrant for my taste (or my monitor)</td>', 'Use of Light:2Focus:1Composition:2Creativity:1Achieves Challenge:2 I really like the motion that the leaves give to the photo.  Use of HDR is pretty subtle (a good thing!) but the colors seem a tad vibrant for my taste (or my monitor)', '2006-11-14 20:36:30.000000', NULL, 1),
(3031593, 426392, 32968, '<td valign="top">Love the crispness of the blooms</td>', 'Love the crispness of the blooms', '2006-11-14 20:36:52.000000', NULL, 1),
(3031594, 426125, 67152, '<td valign="top">Use of Light:1<br/>Focus:1<br/>Composition:2<br/>Creativity:1<br/>Achieves Challenge:2<br/> <br/>Great tree!  Too bad the power lines and the fence are in view.  Good use of HDR to bring out the branches in the shadows.</td>', 'Use of Light:1Focus:1Composition:2Creativity:1Achieves Challenge:2 Great tree!  Too bad the power lines and the fence are in view.  Good use of HDR to bring out the branches in the shadows.', '2006-11-14 20:37:53.000000', NULL, 1),
(3031595, 426523, 32968, '<td valign="top">Nice caption! Works very well for the pic</td>', 'Nice caption! Works very well for the pic', '2006-11-14 20:38:04.000000', NULL, 1),
