(3044221, 426246, 19982, '<td valign="top">Bumping to 10, my pick for the blue.</td>', 'Bumping to 10, my pick for the blue.', '2006-11-19 18:04:46.000000', NULL, 1),
(3044224, 426485, 19982, '<td valign="top">I like this one a lot!  I''d like it more if the guy''s face were more clearly in focus.  This is in my top 3 picks.</td>', 'I like this one a lot!  I''d like it more if the guy''s face were more clearly in focus.  This is in my top 3 picks.', '2006-11-19 18:05:51.000000', NULL, 1),
