INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3044753, 426768, 22748, '<td valign="top">I like the scene. The old wood of the barn has a nice texture to it. <br/> <br/>The only thing I don''t like is the distracting halo in the sky above the trees and above the barn roof. There''s kind of a bright glow in the sky that looks artificial.</td>', 'I like the scene. The old wood of the barn has a nice texture to it.  The only thing I don''t like is the distracting halo in the sky above the trees and above the barn roof. There''s kind of a bright glow in the sky that looks artificial.', '2006-11-19 21:31:33.000000', NULL, 1),
(3044756, 426745, 22748, '<td valign="top">This image seems kind of washed out and low-contrast to me. Perhaps the tone mapping could use a little work?</td>', 'This image seems kind of washed out and low-contrast to me. Perhaps the tone mapping could use a little work?', '2006-11-19 21:32:10.000000', NULL, 1),
(3044763, 426766, 22748, '<td valign="top">Nice composition. I like the interesting patterns in the rocks and the trickle of the waterfalls. It has a nice smooth painterly feel to it. Nice reflection. <br/> <br/>I wonder though if there is anything above the top of the frame that would add to the photo? My eye is drawn up to the top of the frame but it''s cut off. Perhaps if the camera angle were raised a tiny bit--enough to exclude the rock at the bottom of the frame and perhaps include more space at the top so my eye doesn''t feel like it''s being held back from seeing something.<br/> <br/>I must say, great photo.</td>', 'Nice composition. I like the interesting patterns in the rocks and the trickle of the waterfalls. It has a nice smooth painterly feel to it. Nice reflection.  I wonder though if there is anything above the top of the frame that would add to the photo? My eye is drawn up to the top of the frame but it''s cut off. Perhaps if the camera angle were raised a tiny bit--enough to exclude the rock at the bottom of the frame and perhaps include more space at the top so my eye doesn''t feel like it''s being held back from seeing something. I must say, great photo.', '2006-11-19 21:35:17.000000', NULL, 1),
(3044905, 426498, 65025, '<td valign="top">Really lovely photo!  It must have been hard to keep her really still for a bunch of exposures.</td>', 'Really lovely photo!  It must have been hard to keep her really still for a bunch of exposures.', '2006-11-19 22:42:36.000000', NULL, 1),
(3044908, 426226, 65025, '<td valign="top">Wow, there are so many different tones of different colors.  So much detail.  Looks great!</td>', 'Wow, there are so many different tones of different colors.  So much detail.  Looks great!', '2006-11-19 22:43:46.000000', NULL, 1),
(3044911, 426768, 65025, '<td valign="top">It looks really nice, except the sky kind of has a line between it and the barn/trees.</td>', 'It looks really nice, except the sky kind of has a line between it and the barn/trees.', '2006-11-19 22:44:48.000000', NULL, 1),
(3044912, 426824, 65025, '<td valign="top">Looks really nice!</td>', 'Looks really nice!', '2006-11-19 22:45:48.000000', NULL, 1),
(3044913, 426503, 65025, '<td valign="top">Wow, this looks amazing.  It looks SO 3D!</td>', 'Wow, this looks amazing.  It looks SO 3D!', '2006-11-19 22:46:12.000000', NULL, 1),
(3044916, 426303, 65025, '<td valign="top">It looks very cool.  The only thing I would like is for the technique to be a little more subtle.  But it is very nice.  8</td>', 'It looks very cool.  The only thing I would like is for the technique to be a little more subtle.  But it is very nice.  8', '2006-11-19 22:47:45.000000', NULL, 1),
(3044919, 426485, 65025, '<td valign="top">It looks really great, it just seems a little over saturated.  8</td>', 'It looks really great, it just seems a little over saturated.  8', '2006-11-19 22:50:08.000000', NULL, 1),
(3044922, 426155, 65025, '<td valign="top">The bottome half looks really nice, but the top half still seems overexposed.  Maybe a few more exposures could have fixed that.  6</td>', 'The bottome half looks really nice, but the top half still seems overexposed.  Maybe a few more exposures could have fixed that.  6', '2006-11-19 22:53:08.000000', NULL, 1),
(3044924, 426253, 65025, '<td valign="top">I like the line of the tracks.  It adds a nice dynamic.</td>', 'I like the line of the tracks.  It adds a nice dynamic.', '2006-11-19 22:53:54.000000', NULL, 1),
(3044925, 426521, 65025, '<td valign="top">I would have liked to see more detail in the sky.</td>', 'I would have liked to see more detail in the sky.', '2006-11-19 22:54:16.000000', NULL, 1),
(3044927, 426246, 65025, '<td valign="top">It''s very gothic, not only because of the architecture itself, but the extra tones you added.</td>', 'It''s very gothic, not only because of the architecture itself, but the extra tones you added.', '2006-11-19 22:55:58.000000', NULL, 1),
